const PREDEFINED_REQUESTS = [
 { text: 'Condimentos para ensalada', icon: 'condimentos', component: CondimentosIcon },
 { text: 'Traer sal y pimienta', icon: 'sal_pimienta', component: SalPimientaIcon },
 { text: 'Traer queso rallado', icon: 'queso', component: QuesoRalladoIcon },
 { text: 'Acercarse', icon: 'person_pin', component: null },
 { text: 'Otro...', icon: 'more_horiz', component: null }
];

const WaiterRequestModal: React.FC<WaiterRequestModalProps> = ({ 
 isOpen, 
 onClose, 
 waiter, 
 tableNumber,
 orderId 
}) => {
 const [selectedRequest, setSelectedRequest] = useState<string | null>(null);
 const [customMessage, setCustomMessage] = useState('');
 const [isSubmitting, setIsSubmitting] = useState(false);

 if (!isOpen) return null;

 const handleRequestSelect = (requestText: string) => {
 if (requestText === 'Otro...') {
 setSelectedRequest('Otro...');
 } else {
 setSelectedRequest(requestText);
 handleSendRequest(requestText);
 }
 };

 const handleSendRequest = async (message: string) => {
 if (!waiter?.id || !orderId || !tableNumber) {
 console.error('[WaiterRequestModal] Faltan datos necesarios para enviar la solicitud');
 alert('No se pudo enviar la solicitud. Por favor, intenta de nuevo.');
 return;
 }

 setIsSubmitting(true);
 try {
 // Insertar notificación en la tabla waiter_notifications
 const { error } = await supabase
 .from('waiter_notifications')
 .insert({
 waiter_id: waiter.id,
 order_id: orderId,
 table_number: tableNumber,
 message: message,
 status: 'pending',
 created_at: new Date().toISOString()
 });

 if (error) {
 console.error('[WaiterRequestModal] Error al enviar notificación:', error);
 throw error;
 }

 // Cerrar modal y resetear estado
 onClose();
 setSelectedRequest(null);
 setCustomMessage('');
 
 // Mostrar confirmación
 alert('Solicitud enviada al mesero');
 } catch (error) {
 console.error('[WaiterRequestModal] Error:', error);
 alert('Error al enviar la solicitud. Por favor, intenta de nuevo.');
 } finally {
 setIsSubmitting(false);
 }
 };

 const handleSendCustomMessage = () => {
 if (!customMessage.trim()) {
 alert('Por favor, ingresa un mensaje');
 return;
 }
 if (customMessage.length > 128) {
 alert('El mensaje no puede tener más de 128 caracteres');
 return;
 }
 handleSendRequest(customMessage.trim());
 };

 const waiterName = waiter?.full_name && waiter?.nickname 
 ? `${waiter.full_name} ${waiter.nickname}`
 : waiter?.nickname || waiter?.full_name || 'Mesero';

  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="waiter-request-modal-title"
      onClick={onClose}
    >
      <div
        className="bg-surface-dark rounded-3xl shadow-2xl max-w-md w-full max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header con botón cerrar */}
        <div className="sticky top-0 bg-surface-dark border-b border-border-dark p-4 flex items-center justify-between z-10">
          <h2 id="waiter-request-modal-title" className="text-xl font-bold text-white flex-1 text-center">Solicitar al Mesero</h2>
 <button
 onClick={onClose}
 className="text-text-secondary hover:text-white transition-colors ml-auto"
 >
 <span className="material-symbols-outlined">close</span>
 </button>
 </div>

 {/* Waiter Info - Centrado */}
 <div className="p-6 border-b border-border-dark ">
 <div className="flex flex-col items-center text-center">
 <img
 src={waiter?.profile_photo_url || 'https://lh3.googleusercontent.com/aida-public/AB6AXuDyiwOtsINFh8RspVDg_Wx4QKXthNxCS7ZJlDSZvL6ADwFD3WRUpKHGhrscxV9dcR7w7guM4E-iFCNXx-tDgHs1BrbfGjolJoASehM-SEc4Pe6bKEx7zjcF4WAcON7mbdWJCepEdMPkBZ36lB_4tPTsJeNzTNqRNGKgusVb3U_X0WGEAgij6Y48HIunhj_BC8lxMdsB5ublmAltnyYerUKa_NkT8aybLFkaaRkQGQ_irdtS2ZQwrNGNj6b1ZrWY1HRClBeExJL615bG'}
 alt={waiterName}
 className="size-24 rounded-full object-cover border-2 border-primary/30 mb-3"
 />
 <h3 className="text-lg font-bold text-white mb-1">
 {waiterName}
 </h3>
 {waiter?.average_rating && (
 <div className="flex items-center gap-1">
 <span className="material-symbols-outlined text-amber-400 text-sm filled">star</span>
 <span className="text-sm font-bold text-text-secondary">
 {waiter.average_rating.toFixed(1)}
 </span>
 </div>
 )}
 </div>
 </div>

 {/* Request Buttons */}
 <div className="p-6">
 <p className="text-center text-sm text-text-secondary mb-4">¿Cómo podemos ayudarte hoy?</p>
 <div className="flex flex-col gap-3">
 {PREDEFINED_REQUESTS.map((request) => (
 <button
 key={request.text}
 onClick={() => handleRequestSelect(request.text)}
 disabled={isSubmitting}
 className={`w-full flex items-center justify-between px-4 py-3 rounded-xl border-2 transition-all ${
 selectedRequest === request.text
 ? 'border-primary bg-primary/10 '
 : 'border-border-dark bg-surface-dark hover:border-primary/50'
 } ${isSubmitting ? 'opacity-50 cursor-not-allowed' : ''}`}
 >
 <div className="flex items-center gap-3">
 {request.component ? (
 <request.component className={`w-6 h-6 ${
 selectedRequest === request.text ? 'text-primary' : 'text-primary/60'
 }`} />
 ) : (
 <span className={`material-symbols-outlined text-lg ${
 selectedRequest === request.text ? 'text-primary' : 'text-primary/60'
 }`}>
 {request.icon}
 </span>
 )}
 <span className="text-white font-medium">{request.text}</span>
 </div>
 <div className={`size-5 rounded-full border-2 flex items-center justify-center ${
 selectedRequest === request.text
 ? 'border-primary bg-primary'
 : 'border-white/20 '
 }`}>
 {selectedRequest === request.text && (
 <div className="size-2 rounded-full bg-white"></div>
 )}
 </div>
 </button>
 ))}
 </div>

 {/* Custom Message Input */}
 {selectedRequest === 'Otro...' && (
 <div className="mt-6 space-y-3">
 <textarea
 value={customMessage}
 onChange={(e) => {
 const value = e.target.value;
 if (value.length <= 128) {
 setCustomMessage(value);
 }
 }}
 placeholder="Escribe tu solicitud aquí..."
 className="w-full px-4 py-3 rounded-2xl border-2 border-border-dark bg-white/5 text-white placeholder:text-white/30 focus:outline-none focus:border-primary resize-none"
 style={{ borderRadius: '16px' }}
 rows={4}
 maxLength={128}
 />
 <div className="flex items-center justify-between text-xs text-text-secondary">
 <span>{customMessage.length}/128 caracteres</span>
 </div>
 <button
 onClick={handleSendCustomMessage}
 disabled={isSubmitting || !customMessage.trim()}
 className={`w-full bg-primary hover:bg-primary-dark text-black font-bold py-3 rounded-xl transition-all ${
 isSubmitting || !customMessage.trim()
 ? 'opacity-50 cursor-not-allowed'
 : ''
 }`}
 >
 Enviar Solicitud
 </button>
 <button
 onClick={onClose}
 className="w-full text-center text-text-secondary hover:text-white py-2 text-sm transition-colors"
 >
 Cancelar
 </button>
 </div>
 )}
 </div>
 </div>
 </div>
 );
};

export default WaiterRequestModal;
